/**
 * What the Team server runs of Studio, and nothing else.
 *
 * Team is the authority over a team project: it applies every operation itself and broadcasts what
 * it did. For the document it holds to be the document every Studio holds, it has to apply an
 * operation with **the same code** the editor does - so this file is the entry the Team repository
 * bundles (`studio-kernel/` there, regenerated by its `scripts/vendor-studio.mjs`) and runs as an
 * opaque function over JSON. Team never models these types; it hands documents and operations
 * through.
 *
 * ⚠ **Everything exported here is a contract with a server that may be a release behind or ahead.**
 * Add freely; rename or change a signature only together with the Team side, and bump
 * {@link KERNEL_VERSION} whenever the same operation could produce a different document - a Studio
 * and a server on different kernel versions must refuse each other rather than drift apart.
 *
 * Pure only: no services, no Electron, no React, no disk. A module that is not pure does not belong
 * in this graph, and the bundle step is where that shows.
 */
export { applyStoryOpToDocument, storyOpSceneReach, firstSceneId } from "@shared/story/applyStoryOp";
export type { StoryOpApplied, StoryOpApplyContext } from "@shared/story/applyStoryOp";
export { opClaimKeys } from "@shared/live/ops";

/**
 * Which behaviour of the appliers this is. A Studio and a Team server compare it on connecting, and
 * a mismatch is refused: two machines applying the same operation differently is silent divergence.
 */
export const KERNEL_VERSION = 3;

export {
    STORY_LIBRARY_PATH,
    applyStoryOpToLibrary,
    parseStoryDocument,
    parseStoryLibrary,
    serializeStoryFile,
    storyDocumentPath,
} from "./storyFiles";

export {
    applyProjectOp,
    ASSET_CONTENT_ROOT,
    assetBytesOf,
    fileBytesOf,
    fileClaimKey,
    isHeldFile,
    isProjectDocumentPath,
    isTeamFilePath,
    isWholeFilePath,
    parseProjectFile,
    projectDocumentPath,
    projectOpClaimKeys,
    serializeProjectFile,
    STORY_LIBRARY_FILE,
} from "./project";
export type {
    HeldFile,
    KernelProjectView,
    ProjectDocument,
    ProjectOp,
    ProjectOpApplied,
    TeamFileContent,
    TeamFileDocument,
    TeamFileOp,
    TeamStoryLibraryOp,
} from "./project";
